#!/usr/bin/env python3
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{label}: expected exactly one anchor, found {count}")
    return text.replace(old, new, 1)


def patch_encounter() -> None:
    path = ROOT / "Assets/Scripts/EncounterWarfareV130.cs"
    s = path.read_text(encoding="utf-8")

    old_policy = """        public static EagleDefensePlanV130 EagleDefenseFor(EncounterPlan plan)\n        {\n            float pressure = Mathf.Clamp01(plan.EaglePressure);\n            int tier = pressure >= 0.78f ? 3 : pressure >= 0.52f ? 2 : 1;\n            int wallHp = tier == 3 ? 4 : tier == 2 ? 3 : 2;\n            return new EagleDefensePlanV130\n            {\n                Tier = tier,\n                WallHitPoints = wallHp,\n                SteelSides = tier >= 2,\n                SteelCrown = tier >= 3\n            };\n        }\n"""
    new_policy = """        public static EagleDefensePlanV130 EagleDefenseFor(EncounterPlan plan)\n        {\n            float pressure = Mathf.Clamp01(plan.EaglePressure);\n            int tier = pressure >= 0.78f ? 3 : pressure >= 0.52f ? 2 : 1;\n            int wallHp = tier == 3 ? 4 : tier == 2 ? 3 : 2;\n            return new EagleDefensePlanV130\n            {\n                Tier = tier,\n                WallHitPoints = wallHp,\n                CrownHitPoints = Mathf.Clamp(wallHp + (tier >= 3 ? 1 : 0), 2, 5),\n                SteelSides = tier >= 2,\n                // The center approach deliberately remains Brick so every ammo loadout has a visible breach lane.\n                // Steel is reserved for the flanking shoulders and is still breachable by heavy ordnance.\n                SteelCrown = false,\n                DestructibleBreachLane = true\n            };\n        }\n"""
    s = replace_once(s, old_policy, new_policy, "safe Orzelek defense policy")

    old_struct = """    public struct EagleDefensePlanV130\n    {\n        public int Tier;\n        public int WallHitPoints;\n        public bool SteelSides;\n        public bool SteelCrown;\n    }\n\n    /// <summary>Pure phase policy used by the real boss weapon authority.</summary>\n"""
    cross_stack = """    public struct EagleDefensePlanV130\n    {\n        public int Tier;\n        public int WallHitPoints;\n        public int CrownHitPoints;\n        public bool SteelSides;\n        public bool SteelCrown;\n        public bool DestructibleBreachLane;\n    }\n\n    /// <summary>\n    /// Read-only readiness snapshot from the six v12 operational systems named by the v13.0 roadmap.\n    /// Values are player-readiness scores in [0,1]; inactive systems are neutral and do not increase\n    /// ActiveChannels. No state is written back to any v12 director.\n    /// </summary>\n    public struct EncounterReadinessV130\n    {\n        public float MobileFront;\n        public float Sustainment;\n        public float RouteIntelligence;\n        public float ReconEw;\n        public float MobileSignal;\n        public float Sigint;\n        public float Composite;\n        public int ActiveChannels;\n        public int Signature;\n    }\n\n    public struct EncounterRuntimeBudgetV130\n    {\n        public int MaxAlive;\n        public float SpawnInterval;\n        public int ConcurrencyDelta;\n        public float Readiness;\n        public int ActiveChannels;\n        public int Signature;\n    }\n\n    /// <summary>\n    /// v13.0 cross-system doctrine adapter. It consumes only public, read-only state from Mobile Front,\n    /// Operational Sustainment, Route Intelligence, Recon/EW, Mobile Signal and SIGINT. The resulting\n    /// bounded budget is advisory to TankGame, which remains the sole round/spawn authority.\n    /// </summary>\n    public static class EncounterCrossSystemDoctrineV130\n    {\n        public const int MaxConcurrencyDelta = 1;\n        public const float MinSpawnScale = 0.92f;\n        public const float MaxSpawnScale = 1.10f;\n        public const float RefreshSeconds = 0.75f;\n\n        public static bool ConfigurationValid =>\n            MaxConcurrencyDelta == 1 && RefreshSeconds >= 0.5f && RefreshSeconds <= 1.0f &&\n            MinSpawnScale >= 0.90f && MinSpawnScale < 1f && MaxSpawnScale > 1f && MaxSpawnScale <= 1.12f;\n\n        public static EncounterReadinessV130 CaptureReadOnly()\n        {\n            EncounterReadinessV130 snapshot = NeutralSnapshot();\n            float sum = 0f;\n            int active = 0;\n\n            CombinedArmsMobileFrontDirector front = CombinedArmsMobileFrontDirector.Instance;\n            if (front != null && front.IsOperationActive)\n            {\n                snapshot.MobileFront = front.CurrentKind == MobileFrontOperationKind.FriendlyAdvance ? 0.84f :\n                                       front.CurrentKind == MobileFrontOperationKind.EnemyBreakthrough ? 0.18f : 0.50f;\n                AddActive(snapshot.MobileFront, ref sum, ref active);\n            }\n\n            OperationalSustainmentDirector sustain = OperationalSustainmentDirector.Instance;\n            if (sustain != null && (sustain.ColumnActive || sustain.EnemySustainmentDeficit))\n            {\n                if (sustain.EnemySustainmentDeficit) snapshot.Sustainment = 0.78f;\n                else if (sustain.ColumnTeam == Team.Player)\n                {\n                    float manifest = (\n                        Mathf.Clamp01(sustain.FuelRemaining / (float)OperationalSustainmentDirector.FuelMax) +\n                        Mathf.Clamp01(sustain.AmmoRemaining / (float)OperationalSustainmentDirector.AmmoMax) +\n                        Mathf.Clamp01(sustain.RepairRemaining / (float)OperationalSustainmentDirector.RepairMax)) / 3f;\n                    snapshot.Sustainment = Mathf.Clamp01(0.56f + manifest * 0.38f);\n                }\n                else snapshot.Sustainment = 0.22f;\n                AddActive(snapshot.Sustainment, ref sum, ref active);\n            }\n\n            LogisticsRouteIntelligenceDirector route = LogisticsRouteIntelligenceDirector.Instance;\n            if (route != null && route.RouteActive)\n            {\n                float intel = route.IntelState == RouteIntelState.Verified ? 0.88f :\n                              route.IntelState == RouteIntelState.Contact ? 0.56f : 0.26f;\n                float threat = Mathf.Clamp01(route.CurrentThreat / LogisticsRouteIntelligenceDirector.ForceRerouteThreat);\n                bool enemyColumn = sustain != null && sustain.ColumnTeam == Team.Enemy;\n                snapshot.RouteIntelligence = Mathf.Clamp01(intel + (enemyColumn ? threat * 0.10f : -threat * 0.18f) - (route.DecoyActive ? 0.06f : 0f));\n                AddActive(snapshot.RouteIntelligence, ref sum, ref active);\n            }\n\n            ReconElectronicWarfareDirector recon = ReconElectronicWarfareDirector.Instance;\n            if (recon != null && recon.OperationActive)\n            {\n                snapshot.ReconEw = Mathf.Clamp01(0.14f + recon.SignalQuality * 0.72f +\n                                                  (recon.CounterJammingActive ? 0.14f : 0f) -\n                                                  (recon.SpoofRisk ? 0.16f : 0f) -\n                                                  (recon.EffectiveJammerActive ? 0.08f : 0f));\n                AddActive(snapshot.ReconEw, ref sum, ref active);\n            }\n\n            MobileSignalWarfareDirector mobileSignal = MobileSignalWarfareDirector.Instance;\n            if (mobileSignal != null && mobileSignal.OperationActive)\n            {\n                snapshot.MobileSignal = mobileSignal.ObjectiveResolved ? 1f :\n                    Mathf.Clamp01(0.24f + mobileSignal.InterceptProgress01 * 0.58f + (mobileSignal.MobileJammerActive ? 0f : 0.14f));\n                AddActive(snapshot.MobileSignal, ref sum, ref active);\n            }\n\n            SignalsIntelligenceFireSupportDirector sigint = SignalsIntelligenceFireSupportDirector.Instance;\n            if (sigint != null && sigint.OperationActive)\n            {\n                snapshot.Sigint = Mathf.Clamp01(0.16f + sigint.TriangulationQuality * 0.48f +\n                                                (sigint.TrueSignalVerified ? 0.18f : 0f) +\n                                                (sigint.DecoySignalVerified ? 0.08f : 0f) +\n                                                (sigint.FireSupportWindowActive ? 0.18f : 0f));\n                AddActive(snapshot.Sigint, ref sum, ref active);\n            }\n\n            snapshot.ActiveChannels = active;\n            snapshot.Composite = active > 0 ? Mathf.Clamp01(sum / active) : 0.50f;\n            snapshot.Signature = SnapshotSignature(snapshot);\n            return snapshot;\n        }\n\n        public static EncounterReadinessV130 UniformSnapshot(float readiness, int activeChannels)\n        {\n            float value = Mathf.Clamp01(readiness);\n            EncounterReadinessV130 snapshot = new EncounterReadinessV130\n            {\n                MobileFront = value, Sustainment = value, RouteIntelligence = value,\n                ReconEw = value, MobileSignal = value, Sigint = value,\n                Composite = value, ActiveChannels = Mathf.Clamp(activeChannels, 0, 6)\n            };\n            snapshot.Signature = SnapshotSignature(snapshot);\n            return snapshot;\n        }\n\n        public static EncounterRuntimeBudgetV130 Resolve(EncounterPlan plan, EncounterReadinessV130 snapshot)\n        {\n            float readiness = snapshot.ActiveChannels > 0 ? Mathf.Clamp01(snapshot.Composite) : 0.50f;\n            int delta = readiness <= 0.34f ? MaxConcurrencyDelta : readiness >= 0.66f ? -MaxConcurrencyDelta : 0;\n            int maxAlive = Mathf.Clamp(plan.MaxAlive + delta, 4, EncounterPlannerV130.MaxConcurrentEnemies);\n            float scale = Mathf.Clamp(1f + (readiness - 0.50f) * 0.24f, MinSpawnScale, MaxSpawnScale);\n            float interval = Mathf.Clamp(plan.SpawnInterval * scale, EncounterPlannerV130.MinSpawnInterval, EncounterPlannerV130.MaxSpawnInterval);\n            int signature = unchecked(plan.Signature * 31 + snapshot.Signature * 17 + maxAlive * 7 + Mathf.RoundToInt(interval * 1000f));\n            return new EncounterRuntimeBudgetV130\n            {\n                MaxAlive = maxAlive, SpawnInterval = interval, ConcurrencyDelta = delta,\n                Readiness = readiness, ActiveChannels = snapshot.ActiveChannels, Signature = signature\n            };\n        }\n\n        private static EncounterReadinessV130 NeutralSnapshot()\n        {\n            return UniformSnapshot(0.50f, 0);\n        }\n\n        private static void AddActive(float value, ref float sum, ref int active)\n        {\n            sum += Mathf.Clamp01(value);\n            active++;\n        }\n\n        private static int SnapshotSignature(EncounterReadinessV130 s)\n        {\n            int hash = 23;\n            hash = unchecked(hash * 31 + Mathf.RoundToInt(s.MobileFront * 1000f));\n            hash = unchecked(hash * 31 + Mathf.RoundToInt(s.Sustainment * 1000f));\n            hash = unchecked(hash * 31 + Mathf.RoundToInt(s.RouteIntelligence * 1000f));\n            hash = unchecked(hash * 31 + Mathf.RoundToInt(s.ReconEw * 1000f));\n            hash = unchecked(hash * 31 + Mathf.RoundToInt(s.MobileSignal * 1000f));\n            hash = unchecked(hash * 31 + Mathf.RoundToInt(s.Sigint * 1000f));\n            hash = unchecked(hash * 31 + s.ActiveChannels);\n            return hash;\n        }\n    }\n\n    /// <summary>Pure phase policy used by the real boss weapon authority.</summary>\n"""
    s = replace_once(s, old_struct, cross_stack, "cross-system doctrine insertion")
    path.write_text(s, encoding="utf-8")


def patch_tank_game() -> None:
    path = ROOT / "Assets/Scripts/TankGame.cs"
    s = path.read_text(encoding="utf-8")

    fields = """        private int _spawnOrdinal;\n        private EncounterPlan _encounterPlan;\n        private float _roundClearAt = -1f;\n"""
    fields_new = """        private int _spawnOrdinal;\n        private EncounterPlan _encounterPlan;\n        private EncounterRuntimeBudgetV130 _encounterRuntimeBudget;\n        private float _nextEncounterDoctrineRefresh;\n        private float _roundClearAt = -1f;\n"""
    s = replace_once(s, fields, fields_new, "TankGame cross-system budget fields")

    props = """        public int CurrentRound => _round;\n        public EncounterPlan CurrentEncounterPlan => _encounterPlan;\n"""
    props_new = """        public int CurrentRound => _round;\n        public EncounterPlan CurrentEncounterPlan => _encounterPlan;\n        public EncounterRuntimeBudgetV130 CurrentEncounterRuntimeBudget => _encounterRuntimeBudget;\n"""
    s = replace_once(s, props, props_new, "TankGame runtime budget property")

    begin = """            _encounterPlan = EncounterPlannerV130.PlanForRound(round);\n            _enemiesToSpawn = _encounterPlan.EnemyCount;\n            _maxAlive = _encounterPlan.MaxAlive;\n            _bossPending = _encounterPlan.BossRound;\n            _spawnOrdinal = 0;\n            _nextSpawn = Time.time + _encounterPlan.SpawnInterval;\n"""
    begin_new = """            _encounterPlan = EncounterPlannerV130.PlanForRound(round);\n            _enemiesToSpawn = _encounterPlan.EnemyCount;\n            _encounterRuntimeBudget = EncounterCrossSystemDoctrineV130.Resolve(_encounterPlan, EncounterCrossSystemDoctrineV130.CaptureReadOnly());\n            _maxAlive = _encounterRuntimeBudget.MaxAlive;\n            _bossPending = _encounterPlan.BossRound;\n            _spawnOrdinal = 0;\n            _nextEncounterDoctrineRefresh = Time.time + EncounterCrossSystemDoctrineV130.RefreshSeconds;\n            _nextSpawn = Time.time + _encounterRuntimeBudget.SpawnInterval;\n"""
    s = replace_once(s, begin, begin_new, "TankGame BeginRound cross-system consumption")

    handle = """        private void HandleSpawning()\n        {\n            if (_aliveEnemies >= _maxAlive || Time.time < _nextSpawn) return;\n"""
    handle_new = """        private void RefreshEncounterDoctrineBudget()\n        {\n            if (Time.time < _nextEncounterDoctrineRefresh) return;\n            _nextEncounterDoctrineRefresh = Time.time + EncounterCrossSystemDoctrineV130.RefreshSeconds;\n            EncounterReadinessV130 readiness = EncounterCrossSystemDoctrineV130.CaptureReadOnly();\n            _encounterRuntimeBudget = EncounterCrossSystemDoctrineV130.Resolve(_encounterPlan, readiness);\n            _maxAlive = _encounterRuntimeBudget.MaxAlive;\n        }\n\n        private void HandleSpawning()\n        {\n            RefreshEncounterDoctrineBudget();\n            if (_aliveEnemies >= _maxAlive || Time.time < _nextSpawn) return;\n"""
    s = replace_once(s, handle, handle_new, "TankGame live cross-system refresh")

    spawn_interval = """                _nextSpawn = Time.time + Mathf.Max(EncounterPlannerV130.MinSpawnInterval, _encounterPlan.SpawnInterval);\n"""
    spawn_interval_new = """                _nextSpawn = Time.time + Mathf.Max(EncounterPlannerV130.MinSpawnInterval, _encounterRuntimeBudget.SpawnInterval);\n"""
    s = replace_once(s, spawn_interval, spawn_interval_new, "TankGame adaptive bounded spawn interval")

    eagle = """            ObstacleKind sideKind = defense.SteelSides ? ObstacleKind.Steel : ObstacleKind.Brick;\n            ObstacleKind crownKind = defense.SteelCrown ? ObstacleKind.Steel : ObstacleKind.Brick;\n            int wallHp = defense.WallHitPoints;\n            CreateObstacle(new Vector2(-1.15f, -5.85f), sideKind, new Vector2(0.75f, 0.75f), wallHp);\n            CreateObstacle(new Vector2(1.15f, -5.85f), sideKind, new Vector2(0.75f, 0.75f), wallHp);\n            CreateObstacle(new Vector2(-0.75f, -5.05f), crownKind, new Vector2(0.75f, 0.75f), wallHp);\n            CreateObstacle(new Vector2(0.75f, -5.05f), crownKind, new Vector2(0.75f, 0.75f), wallHp);\n"""
    eagle_new = """            ObstacleKind sideKind = defense.SteelSides ? ObstacleKind.Steel : ObstacleKind.Brick;\n            ObstacleKind crownKind = ObstacleKind.Brick; // permanent universal-ammo breach lane\n            int wallHp = defense.WallHitPoints;\n            CreateObstacle(new Vector2(-1.15f, -5.85f), sideKind, new Vector2(0.75f, 0.75f), wallHp);\n            CreateObstacle(new Vector2(1.15f, -5.85f), sideKind, new Vector2(0.75f, 0.75f), wallHp);\n            CreateObstacle(new Vector2(-0.75f, -5.05f), crownKind, new Vector2(0.75f, 0.75f), defense.CrownHitPoints);\n            CreateObstacle(new Vector2(0.75f, -5.05f), crownKind, new Vector2(0.75f, 0.75f), defense.CrownHitPoints);\n"""
    s = replace_once(s, eagle, eagle_new, "TankGame safe Eagle breach lane")

    hud = """            GUI.Box(new Rect(14f, 12f, 480f, 158f), string.Empty);\n"""
    hud_new = """            GUI.Box(new Rect(14f, 12f, 480f, 183f), string.Empty);\n"""
    s = replace_once(s, hud, hud_new, "TankGame telemetry panel height")

    hud_line = """            GUI.Label(new Rect(28f, 128f, 455f, 25f), $\"THREAT {_encounterPlan.EnemyCount}/{_encounterPlan.MaxAlive}   EAGLE P{Mathf.RoundToInt(_encounterPlan.EaglePressure * 100f):00}   SIG {_encounterPlan.Signature:X8}{bossTelemetry}\", _smallStyle);\n"""
    hud_line_new = hud_line + """            GUI.Label(new Rect(28f, 153f, 455f, 25f), $\"XSYS {_encounterRuntimeBudget.ActiveChannels}/6   READY {Mathf.RoundToInt(_encounterRuntimeBudget.Readiness * 100f):00}%   CONC {_encounterRuntimeBudget.ConcurrencyDelta:+#;-#;0}   RT {_encounterRuntimeBudget.Signature:X8}\", _smallStyle);\n"""
    s = replace_once(s, hud_line, hud_line_new, "TankGame cross-system HUD telemetry")
    path.write_text(s, encoding="utf-8")


def patch_smoke() -> None:
    path = ROOT / "Assets/Scripts/EncounterWarfareCISmokeProbe.cs"
    s = path.read_text(encoding="utf-8")

    defense = """                if (earlyDefense.Tier < 1 || lateDefense.Tier > 3 ||\n                    earlyDefense.Tier > midDefense.Tier || midDefense.Tier > lateDefense.Tier ||\n                    earlyDefense.WallHitPoints > midDefense.WallHitPoints || midDefense.WallHitPoints > lateDefense.WallHitPoints ||\n                    !lateDefense.SteelSides || !lateDefense.SteelCrown)\n                { Fail(\"Orzelek fortification policy is not bounded/monotonic\"); return; }\n"""
    defense_new = """                if (earlyDefense.Tier < 1 || lateDefense.Tier > 3 ||\n                    earlyDefense.Tier > midDefense.Tier || midDefense.Tier > lateDefense.Tier ||\n                    earlyDefense.WallHitPoints > midDefense.WallHitPoints || midDefense.WallHitPoints > lateDefense.WallHitPoints ||\n                    earlyDefense.CrownHitPoints > midDefense.CrownHitPoints || midDefense.CrownHitPoints > lateDefense.CrownHitPoints ||\n                    !lateDefense.SteelSides || lateDefense.SteelCrown || !lateDefense.DestructibleBreachLane ||\n                    lateDefense.CrownHitPoints < lateDefense.WallHitPoints || lateDefense.CrownHitPoints > 5)\n                { Fail(\"Orzelek fortification policy lost bounded destructible center breach lane\"); return; }\n\n                if (!EncounterCrossSystemDoctrineV130.ConfigurationValid)\n                { Fail(\"cross-system doctrine configuration invalid\"); return; }\n                EncounterPlan pressurePlan = plans[79];\n                EncounterRuntimeBudgetV130 neutralBudget = EncounterCrossSystemDoctrineV130.Resolve(pressurePlan, EncounterCrossSystemDoctrineV130.UniformSnapshot(0.50f, 0));\n                EncounterRuntimeBudgetV130 hostileBudget = EncounterCrossSystemDoctrineV130.Resolve(pressurePlan, EncounterCrossSystemDoctrineV130.UniformSnapshot(0.10f, 6));\n                EncounterRuntimeBudgetV130 favorableBudget = EncounterCrossSystemDoctrineV130.Resolve(pressurePlan, EncounterCrossSystemDoctrineV130.UniformSnapshot(0.90f, 6));\n                if (neutralBudget.ConcurrencyDelta != 0 || neutralBudget.MaxAlive != pressurePlan.MaxAlive ||\n                    hostileBudget.ConcurrencyDelta != 1 || favorableBudget.ConcurrencyDelta != -1 ||\n                    hostileBudget.MaxAlive > EncounterPlannerV130.MaxConcurrentEnemies || favorableBudget.MaxAlive < 4 ||\n                    hostileBudget.SpawnInterval < EncounterPlannerV130.MinSpawnInterval ||\n                    favorableBudget.SpawnInterval > EncounterPlannerV130.MaxSpawnInterval ||\n                    hostileBudget.SpawnInterval >= neutralBudget.SpawnInterval || favorableBudget.SpawnInterval <= neutralBudget.SpawnInterval)\n                { Fail(\"cross-system pressure/relief budget is not bounded and directional\"); return; }\n"""
    s = replace_once(s, defense, defense_new, "v13 smoke fortification/cross-system contracts")

    report = """                    \"spawnFold=\" + spawnFold + \" supplySpawns=\" + supplySpawns + \" fortificationTiers=\" + earlyDefense.Tier + \"/\" + midDefense.Tier + \"/\" + lateDefense.Tier + \"\\n\";\n"""
    report_new = """                    \"spawnFold=\" + spawnFold + \" supplySpawns=\" + supplySpawns + \" fortificationTiers=\" + earlyDefense.Tier + \"/\" + midDefense.Tier + \"/\" + lateDefense.Tier + \" breachLane=\" + lateDefense.DestructibleBreachLane + \"\\n\" +\n                    \"crossSystem=6 channels hostileDelta=\" + hostileBudget.ConcurrencyDelta + \" favorableDelta=\" + favorableBudget.ConcurrencyDelta + \" neutralInterval=\" + neutralBudget.SpawnInterval.ToString(\"0.000\") + \"\\n\";\n"""
    s = replace_once(s, report, report_new, "v13 smoke report expansion")
    path.write_text(s, encoding="utf-8")


def patch_changelog() -> None:
    path = ROOT / "CHANGELOG_v13.0.md"
    s = path.read_text(encoding="utf-8")
    marker = "## Live encounter consumption\n- `TankGame` consumes v13.0 plan budgets, deterministic doctrine composition and Orzelek pressure fortification; HUD exposes exact plan telemetry.\n"
    addition = """\n### Safe Orzelek escalation and cross-stack doctrine\n\n- Tier-3 fortification keeps Steel on the side shoulders but permanently reserves the two center crown blocks as destructible Brick, so Basic/Twin loadouts always retain a visible breach route while heavy ammunition can still crack the tougher flanks.\n- Added `EncounterCrossSystemDoctrineV130`, which reads only public state from Mobile Front, Operational Sustainment, Route Intelligence, Recon/EW, Mobile Signal and SIGINT. It never mutates those services.\n- Active operational readiness now produces a tightly bounded live spawn-pressure decision: at most ±1 concurrent enemy and a 0.92–1.10 spawn-interval scale, refreshed only every 0.75 s while `TankGame` remains the sole spawn authority.\n- The tactical HUD exposes active cross-system channels, composite readiness, bounded concurrency delta and runtime-budget signature.\n- Packaged v13.0 smoke now proves the universal center breach lane plus neutral/hostile/favorable cross-system budget direction and hard limits.\n"""
    if addition.strip() not in s:
        if marker in s:
            s = s.replace(marker, marker + addition, 1)
        else:
            s += "\n" + addition
    path.write_text(s, encoding="utf-8")


def verify() -> None:
    encounter = (ROOT / "Assets/Scripts/EncounterWarfareV130.cs").read_text(encoding="utf-8")
    tank = (ROOT / "Assets/Scripts/TankGame.cs").read_text(encoding="utf-8")
    smoke = (ROOT / "Assets/Scripts/EncounterWarfareCISmokeProbe.cs").read_text(encoding="utf-8")
    changelog = (ROOT / "CHANGELOG_v13.0.md").read_text(encoding="utf-8")
    required = [
        ("safe breach-lane policy", "DestructibleBreachLane = true" in encounter and "SteelCrown = false" in encounter),
        ("cross-system doctrine", "public static class EncounterCrossSystemDoctrineV130" in encounter),
        ("six read-only v12 services", all(name in encounter for name in ["CombinedArmsMobileFrontDirector.Instance", "OperationalSustainmentDirector.Instance", "LogisticsRouteIntelligenceDirector.Instance", "ReconElectronicWarfareDirector.Instance", "MobileSignalWarfareDirector.Instance", "SignalsIntelligenceFireSupportDirector.Instance"])),
        ("bounded runtime budget", "MaxConcurrencyDelta = 1" in encounter and "MinSpawnScale = 0.92f" in encounter and "MaxSpawnScale = 1.10f" in encounter),
        ("TankGame runtime consumption", "EncounterCrossSystemDoctrineV130.CaptureReadOnly()" in tank and "_maxAlive = _encounterRuntimeBudget.MaxAlive;" in tank),
        ("TankGame universal breach lane", "ObstacleKind crownKind = ObstacleKind.Brick" in tank and "defense.CrownHitPoints" in tank),
        ("TankGame cross-system HUD", "XSYS {_encounterRuntimeBudget.ActiveChannels}/6" in tank),
        ("smoke cross-system budgets", "hostileBudget.ConcurrencyDelta != 1" in smoke and "favorableBudget.ConcurrencyDelta != -1" in smoke),
        ("changelog cross-stack section", "Safe Orzelek escalation and cross-stack doctrine" in changelog),
    ]
    failed = [name for name, ok in required if not ok]
    if failed:
        raise SystemExit("verification failed: " + ", ".join(failed))
    forbidden = ["BindingFlags.NonPublic", "GetField(", ".MovePosition(", "SpawnProjectile(", ".Damage(", ".Heal("]
    cross = encounter[encounter.index("public static class EncounterCrossSystemDoctrineV130"):encounter.index("/// <summary>Pure phase policy")]
    for token in forbidden:
        if token in cross:
            raise SystemExit("cross-system doctrine contains forbidden authority token: " + token)
    print("v13.0 safe defense + read-only cross-system doctrine registrar: PASS")


if __name__ == "__main__":
    patch_encounter()
    patch_tank_game()
    patch_smoke()
    patch_changelog()
    verify()
